  const [category,setCategory]=useState("All"); const [status,setStatus]=useState("All"); const [selected,setSelected]=useState<ProjectItem|null>(null); const [loading,setLoading]=useState(false);
  const filter=(setter:(value:string)=>void,value:string)=>{setLoading(true);setter(value);window.setTimeout(()=>setLoading(false),280)};
  useEffect(()=>{document.body.classList.toggle("modal-open",Boolean(selected));if(!selected)return;const close=(e:KeyboardEvent)=>{if(e.key==="Escape")setSelected(null)};window.addEventListener("keydown",close);return()=>{document.body.classList.remove("modal-open");window.removeEventListener("keydown",close)}},[selected]);
