 <section className="section"><div className="container"><SectionTitle eyebrow="Visual mockups" title="Illustrative product screens" text="These interface compositions are visual demonstrations, not screenshots from a live client deployment."/><div className="mockup-grid mt-10">{["Overview dashboard","Primary workflow","Management reporting"].map(title=><div className={`${project.accent} mockup-frame`} key={title} role="img" aria-label={`${project.name}: ${title} illustrative screen`}><div className="mockup-browser"><span></span><span></span><span></span></div><div className="mockup-content"><aside></aside><main><div className="mockup-title"><Icon aria-hidden="true"/><span>{title}</span></div><div className="mockup-cards"><i/><i/><i/></div><div className="mockup-table"><i/><i/><i/><i/></div></main></div></div>)}</div></div></section>
