type EnquiryDraft={fullName:string;organisation:string;email:string;phone:string;contactMethod:string;service:string;budget:string;startDate:string;description:string;consent:boolean};
type EnquiryErrors=Partial<Record<keyof EnquiryDraft,string>>;
const blankEnquiry:EnquiryDraft={fullName:"",organisation:"",email:"",phone:"",contactMethod:"WhatsApp",service:"",budget:"",startDate:"",description:"",consent:false};
export function ContactPage(){
  const [form,setForm]=useState<EnquiryDraft>(blankEnquiry); const [prepared,setPrepared]=useState(false); const [errors,setErrors]=useState<EnquiryErrors>({});
  const contactCards:[LucideIcon,string,string,string][]=[
    [Phone,"Phone",companyConfig.phoneDisplay,companyConfig.phoneLink?`tel:${companyConfig.phoneLink}`:"#enquiry-form"],
    [MessageCircle,"WhatsApp",companyConfig.whatsappDisplay,companyConfig.whatsappNumber?`https://wa.me/${companyConfig.whatsappNumber}`:"#enquiry-form"],
    [Mail,"Email",companyConfig.email,`mailto:${companyConfig.email}`],
    [MapPin,"Location",companyConfig.location,"#harare-map"],
    [Clock,"Business hours",companyConfig.businessHours,"#enquiry-form"]
  ];
  useEffect(()=>{const timer=window.setTimeout(()=>{try{const saved=localStorage.getItem("angress-enquiry-draft");if(saved)setForm({...blankEnquiry,...JSON.parse(saved),consent:false})}catch{}},0);return()=>window.clearTimeout(timer)},[]);
  const update=(field:keyof EnquiryDraft,value:string|boolean)=>{const next={...form,[field]:value};setForm(next);setErrors(current=>({...current,[field]:undefined}));setPrepared(false);try{localStorage.setItem("angress-enquiry-draft",JSON.stringify({...next,consent:false}))}catch{}};
  const validate=()=>{const next:EnquiryErrors={};const required:[keyof EnquiryDraft,string][]=[["fullName","Enter your full name."],["organisation","Enter your organisation name."],["email","Enter your email address."],["phone","Enter your phone number."],["service","Select the service required."],["budget","Select an estimated budget."],["contactMethod","Select a preferred contact method."],["description","Describe your project." ]];required.forEach(([field,message])=>{if(!String(form[field]).trim())next[field]=message});if(form.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(form.email.trim()))next.email="Enter a valid email address.";const phone=form.phone.replace(/[\s()-]/g,"");if(form.phone&&!/^(?:(?:\+263|263|0)7[1-8]\d{7}|(?:\+263|263|0)2\d{7,8})$/.test(phone))next.phone="Use a valid Zimbabwean number, for example +263 77 123 4567.";if(form.description.trim()&&form.description.trim().length<20)next.description="Please provide at least 20 characters so we can understand the project.";if(!form.consent)next.consent="Consent is required before preparing your enquiry.";return next};
  const submit=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const formElement=e.currentTarget;const next=validate();setErrors(next);if(Object.keys(next).length){window.requestAnimationFrame(()=>formElement.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus());return;}
    // DEMONSTRATION SUBMISSION ONLY: no API, email service, database or network request is made here.
    setPrepared(true);setForm(blankEnquiry);try{localStorage.removeItem("angress-enquiry-draft")}catch{};window.dispatchEvent(new CustomEvent("angress-toast",{detail:"Demonstration enquiry prepared successfully."}));setTimeout(()=>document.getElementById("enquiry-result")?.scrollIntoView({behavior:"smooth",block:"center"}),0)};
  return <><PageHero eyebrow="Contact us" title="Let’s Turn Your Idea Into a Practical Plan" text="Tell us what your organisation needs, and prepare a clear enquiry to continue directly by WhatsApp, phone or email."/>
    <section className="contact-cards-section"><div className="container contact-cards">{contactCards.map(([Icon,label,value,href])=><a href={href} className="contact-card" key={label}><span><Icon/></span><div><b>{label}</b><p>{value}</p></div><ArrowRight/></a>)}</div></section>
    <section className="section"><div className="container contact-layout"><aside><SectionTitle eyebrow="Start a conversation" title="Tell us what you want to achieve" text="The form prepares your enquiry on this device only. Nothing is sent until you choose WhatsApp, phone or email."/><div className="privacy-panel"><LockKeyhole/><div><b>Your privacy matters</b><p>No backend, third-party form service or remote database is connected. A draft may be stored temporarily in your browser and can be cleared at any time.</p><button onClick={()=>{localStorage.removeItem("angress-enquiry-draft");setForm(blankEnquiry);setPrepared(false)}}>Clear local draft</button></div></div><div className="contact-reassurance"><ShieldCheck/><div><b>Clear, practical guidance</b><p>We’ll help clarify the right service, realistic project stage and next steps—without pressure or unsupported promises.</p></div></div></aside>
      <form id="enquiry-form" className="project-enquiry-form" onSubmit={submit} noValidate><div className="form-heading"><span>PROJECT ENQUIRY</span><h2>Prepare your project brief</h2><p>Fields marked * are required.</p></div><div className="form-grid">
        <label>Full name *<input autoComplete="name" aria-invalid={!!errors.fullName} aria-describedby={errors.fullName?"fullName-error":undefined} value={form.fullName} onChange={e=>update("fullName",e.target.value)} placeholder="Your full name"/>{errors.fullName&&<span id="fullName-error" className="field-error">{errors.fullName}</span>}</label>
        <label>Organisation name *<input autoComplete="organization" aria-invalid={!!errors.organisation} aria-describedby={errors.organisation?"organisation-error":undefined} value={form.organisation} onChange={e=>update("organisation",e.target.value)} placeholder="Company or institution"/>{errors.organisation&&<span id="organisation-error" className="field-error">{errors.organisation}</span>}</label>
        <label>Email address *<input type="email" inputMode="email" autoComplete="email" aria-invalid={!!errors.email} aria-describedby={errors.email?"email-error":undefined} value={form.email} onChange={e=>update("email",e.target.value)} placeholder="you@organisation.com"/>{errors.email&&<span id="email-error" className="field-error">{errors.email}</span>}</label>
        <label>Phone number *<input type="tel" inputMode="tel" autoComplete="tel" aria-invalid={!!errors.phone} aria-describedby={errors.phone?"phone-error":undefined} value={form.phone} onChange={e=>update("phone",e.target.value)} placeholder="+263 77 123 4567"/>{errors.phone&&<span id="phone-error" className="field-error">{errors.phone}</span>}</label>
        <label>Preferred contact method *<select aria-invalid={!!errors.contactMethod} aria-describedby={errors.contactMethod?"contactMethod-error":undefined} value={form.contactMethod} onChange={e=>update("contactMethod",e.target.value)}><option>WhatsApp</option><option>Phone</option><option>Email</option></select>{errors.contactMethod&&<span id="contactMethod-error" className="field-error">{errors.contactMethod}</span>}</label>
        <label>Service required *<select aria-invalid={!!errors.service} aria-describedby={errors.service?"service-error":undefined} value={form.service} onChange={e=>update("service",e.target.value)}><option value="">Select a service</option>{["Custom Software Development","Website and Web Application Development","Mobile Application Development","IT Consultancy","Cybersecurity Solutions","Data Analytics and Business Intelligence","Digital Marketing","System Maintenance, Technical Support and Training"].map(x=><option key={x}>{x}</option>)}</select>{errors.service&&<span id="service-error" className="field-error">{errors.service}</span>}</label>
        <label>Estimated budget *<select aria-invalid={!!errors.budget} aria-describedby={errors.budget?"budget-error":undefined} value={form.budget} onChange={e=>update("budget",e.target.value)}><option value="">Select a range</option><option>Under US$1,000</option><option>US$1,000–US$3,000</option><option>US$3,000–US$10,000</option><option>US$10,000+</option><option>Not sure—need guidance</option></select>{errors.budget&&<span id="budget-error" className="field-error">{errors.budget}</span>}</label>
        <label>Preferred project start date<span className="date-field"><Calendar/><input type="date" value={form.startDate} onChange={e=>update("startDate",e.target.value)}/></span></label>
        <label className="full-field">Project description *<textarea aria-invalid={!!errors.description} aria-describedby={errors.description?"description-error":undefined} rows={6} value={form.description} onChange={e=>update("description",e.target.value)} placeholder="Describe the problem, intended users and what success would look like."/>{errors.description&&<span id="description-error" className="field-error">{errors.description}</span>}</label>
        <label className="consent-field full-field"><input type="checkbox" aria-invalid={!!errors.consent} aria-describedby={errors.consent?"consent-error":undefined} checked={form.consent} onChange={e=>update("consent",e.target.checked)}/><span>I consent to ANGRESS using the details provided to discuss this enquiry. *{errors.consent&&<em id="consent-error" className="field-error">{errors.consent}</em>}</span></label>
      </div><button type="submit" className="btn-primary enquiry-submit" disabled={!form.consent}><Send/> Prepare Enquiry</button><p className="form-disclaimer"><Eye/> Demonstration submission only. Preparing this form does not transmit any information.</p></form>
    </div></section>
    {prepared&&<section id="enquiry-result" className="prepared-result" role="status" aria-live="polite"><div className="container"><CheckCircle2/><div><span>ENQUIRY PREPARED</span><h2>Your consultation enquiry is ready</h2><p>Thank you for contacting ANGRESS INTELLIGENT TECHNOLOGY. Your enquiry has been prepared successfully. Our team will contact you using the details provided.</p></div></div></section>}
    <section id="harare-map" className="map-section"><div className="container map-placeholder" role="img" aria-label="Map-style illustration locating ANGRESS Intelligent Technology in Harare, Zimbabwe"><div className="map-grid" aria-hidden="true"></div><div className="map-pin" aria-hidden="true"><MapPin/></div><div className="map-label"><span>ANGRESS INTELLIGENT TECHNOLOGY</span><h2>Harare, Zimbabwe</h2><p>Serving organisations in Zimbabwe and across Africa</p></div></div></section>
    <section className="cta-banner"><div className="container relative z-10 flex flex-col items-start justify-between gap-8 py-16 lg:flex-row lg:items-center"><div><span>READY WHEN YOU ARE</span><h2>Let’s Build Something Useful</h2><p>Begin with a clear conversation about the challenge, users and outcome that matter most.</p></div><a href={`mailto:${companyConfig.email}?subject=${encodeURIComponent("Technology project consultation")}`} className="btn-accent">Email Our Team <ArrowRight/></a></div></section>
  </>}

function LegalPage({type}:{type:"privacy"|"terms"}){const privacy=type==="privacy";return <><PageHero eyebrow={privacy?"Privacy policy":"Terms of service"} title={privacy?"Privacy and Your Information":"Website Terms of Service"} text={privacy?"A plain-language overview of how this front-end website handles information.":"Simple terms for using the ANGRESS company profile website."}/><section className="section"><div className="container legal-content"><p className="legal-updated">Last reviewed: August 2026</p>{privacy?<><h2>Front-end-only website</h2><p>This website does not use a backend enquiry database or third-party form submission service. Project enquiry drafts may be stored temporarily in your own browser through localStorage.</p><h2>Information you choose to send</h2><p>Information is transmitted only when you choose a direct channel such as WhatsApp, phone or email. Those channels operate under their respective providers and your own device settings.</p><h2>Your choices</h2><p>You can clear the locally stored enquiry draft from the Contact page. Do not include confidential, financial, medical or security-sensitive information in an initial enquiry.</p><h2>Questions</h2><p>For privacy questions, contact <a href={`mailto:${companyConfig.email}`}>{companyConfig.email}</a>.</p></>:<><h2>Website purpose</h2><p>This website presents ANGRESS INTELLIGENT TECHNOLOGY, its services and a portfolio of concepts, prototypes, active-development projects and internal work.</p><h2>No automatic agreement</h2><p>Submitting or preparing an enquiry does not create a contract, confirm project availability or guarantee a specific outcome. Project scope, fees, responsibilities and timelines require a separate written agreement.</p><h2>Portfolio accuracy</h2><p>Development-stage labels are provided for transparency. No client relationship, deployment or commercial result should be inferred unless explicitly stated.</p><h2>Acceptable use</h2><p>Do not misuse the website, attempt unauthorised access or submit unlawful or harmful content through any contact channel.</p></>}</div></section></>}

function GlobalEnhancements(){
  const [top,setTop]=useState(false); const [cookies,setCookies]=useState(false); const [dark,setDark]=useState(false); const [toast,setToast]=useState("");
  useEffect(()=>{const onScroll=()=>setTop(window.scrollY>500);window.addEventListener("scroll",onScroll,{passive:true});const init=window.setTimeout(()=>{try{setCookies(!localStorage.getItem("angress-cookie-preference"));const saved=localStorage.getItem("angress-theme");const useDark=saved? saved==="dark":window.matchMedia("(prefers-color-scheme: dark)").matches;setDark(useDark);document.documentElement.classList.toggle("dark-theme",useDark)}catch{}},0);const onToast=(e:Event)=>{setToast((e as CustomEvent<string>).detail);window.setTimeout(()=>setToast(""),3200)};window.addEventListener("angress-toast",onToast);return()=>{window.clearTimeout(init);window.removeEventListener("scroll",onScroll);window.removeEventListener("angress-toast",onToast)}},[]);
  const choose=(value:string)=>{localStorage.setItem("angress-cookie-preference",value);setCookies(false);setToast(value==="all"?"Preferences saved.":"Essential storage only.");window.setTimeout(()=>setToast(""),3000)};
  const toggleTheme=()=>{const next=!dark;setDark(next);document.documentElement.classList.toggle("dark-theme",next);localStorage.setItem("angress-theme",next?"dark":"light");setToast(`${next?"Dark":"Light"} theme enabled.`);window.setTimeout(()=>setToast(""),3000)};
  return <><button type="button" className="theme-toggle" onClick={toggleTheme} aria-label={`Switch to ${dark?"light":"dark"} theme`}>{dark?<Sun aria-hidden="true"/>:<Moon aria-hidden="true"/>}</button>{top&&<button type="button" className="back-to-top" onClick={()=>window.scrollTo({top:0,behavior:"smooth"})} aria-label="Back to top"><ArrowUp aria-hidden="true"/></button>}{cookies&&<aside className="cookie-banner" aria-label="Cookie preferences"><Cookie aria-hidden="true"/><div><b>Your browsing preferences</b><p>We use local browser storage only for preferences and optional enquiry drafts—never advertising trackers.</p><Link href="/privacy-policy">Read our privacy policy</Link></div><div><button type="button" onClick={()=>choose("essential")}>Essential only</button><button type="button" className="btn-primary" onClick={()=>choose("all")}>Accept preferences</button></div></aside>}{toast&&<div className="site-toast" role="status" aria-live="polite"><CheckCircle2 aria-hidden="true"/>{toast}</div>}</>;
}

export function CompanyPage({ page }: { page: PageKey }) {
  const content = page === "home" ? <HomePage/> : page === "about" ? <AboutPage/> : page === "services" ? <ServicesPage/> : page === "solutions" ? <SolutionsPage/> : page === "projects" ? <ProjectsPage/> : page === "industries" ? <IndustriesPage/> : page === "privacy-policy" ? <LegalPage type="privacy"/> : page === "terms-of-service" || page === "terms-and-conditions" ? <LegalPage type="terms"/> : <ContactPage/>;
  return content;
}
